python -c "
import json, mido

with open(r'E:\agenthle\audio\music_transcription\dorico_prelude\input\task_brief.json') as f:
    brief = json.load(f)

mf = mido.MidiFile(r'E:\agenthle\audio\music_transcription\dorico_prelude\output\transcription.mid')
# Build name -> (program, is_percussion) for tracks that have program_change
midi_tracks = {}
for tr in mf.tracks:
    name = None
    pc = None
    for msg in tr:
        if msg.type == 'track_name':
            name = msg.name
        if msg.type == 'program_change' and pc is None:
            pc = msg.program
    if name:
        midi_tracks[name] = pc

ok = 0; fail = 0
for instr in brief['instruments']:
    name = instr['name']
    # Normalize name variants
    candidates = [name, name.replace(' [Track]',''), name.split(' (')[0]]
    expected = instr['gm_program']
    found = None
    for c in candidates:
        for mname, pc in midi_tracks.items():
            if mname == c or mname.startswith(c):
                found = (mname, pc); break
        if found: break
    if found:
        mname, pc = found
        status = 'OK' if pc == expected else 'MISMATCH'
        if pc == expected: ok += 1
        else: fail += 1
        print(f'{status:8s} {name:30s} expected={expected}  got={pc}  midi_track={mname}')
    else:
        print(f'NOT_FOUND {name:30s} expected={expected}')
        fail += 1
print(f'\\nTotal OK: {ok}/{len(brief[\"instruments\"])}')
"
